detector_raw:
{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this analysis — are we maximizing the total value of Carelland's exports (engines, electronics, plastic, and any other goods produced for the world market), or is there a different goal such as maximizing imports, minimizing labor, or something else?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting alternatives within one coherent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "How is Carelland's domestic GDP measured in this model — is it the total value of all goods produced domestically (steel, engines, electronics, plastic) valued at the world market prices, or is it something narrower like the value of exports only, or net of the value of imported goods used in production?"
  ],
  "rationale": "The response asks for a single policy/definition choice regarding how GDP is calculated, presenting mutually exclusive options within one sentence."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are steel, engines, electronics, and plastic the only goods Carelland produces, or are there other domestic products (such as food or services) that also count toward GDP and use labor?"
  ],
  "rationale": "The response contains a single clarification question asking for the complete list of domestic products that contribute to GDP and labor usage."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "is there a limit on how many Klunz of imported goods Carelland can obtain per year, or is that input effectively unlimited?"
  ],
  "rationale": "The response asks a single clarification question regarding the availability constraint of imported goods."
}

{
  "action": "question",
  "question_count": 2,
  "is_atomic": false,
  "atomic_questions": [
    "is steel produced domestically (in which case, what are its input requirements and any production limit), or is it imported and therefore not part of the production decisions?"
  ],
  "rationale": "The response asks whether steel is produced domestically or imported. If it is produced domestically, it further asks for its input requirements and production limit. These are two semantically independent requests: the first is a binary status check, and the second is a conditional detail request that only applies if the first answer is 'domestic'."
}

